/// The block name that owns a global state id (binary search over
/// the generated ranges); `None` past the table.
pub fn block_name_of(state_id: u32) -> Option<&'static str> {
    BLOCK_RANGES
        .binary_search_by(|(lo, hi, _)| {
            if state_id < *lo {
                std::cmp::Ordering::Greater
            } else if state_id >= *hi {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .ok()
        .map(|i| BLOCK_RANGES[i].2)
}
